/**
 * Align a PostgreSQL serial/identity sequence with MAX(column) so the next
 * autogenerated key does not collide (e.g. after imports or manual inserts).
 *
 * @param {import("@prisma/client").Prisma.TransactionClient} tx
 * @param {string} table
 * @param {string} column
 */
async function syncPostgresSequence(tx, table, column) {
  await tx.$executeRawUnsafe(`
    SELECT setval(
      pg_get_serial_sequence('${table}', '${column}'),
      COALESCE((SELECT MAX("${column}") FROM "${table}"), 0) + 1,
      false
    )
  `);
}

module.exports = {
  syncPostgresSequence
};
